validator:
function validate([root, fromNode, toNode]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs a root.';
  const values = root.filter(v => v !== null);
  if (values.length < 3 || values.length > 10000) return 'The tree has 3 to 10^4 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < -1000000000 || v > 1000000000)) return 'Node values are whole numbers between -10^9 and 10^9.';
  if (new Set(values).size !== values.length) return 'Node values must be unique.';
  // Walk the level-order array, noting each node's depth, its left-to-right position and whether it has a right child.
  const info = new Map([[root[0], { depth: 0, order: 0, right: false }]]);
  const queue = [root[0]];
  let next = 1;
  for (let head = 0; head < queue.length; head++) {
    for (const side of ['left', 'right']) {
      if (next < root.length && root[next] !== null) {
        info.set(root[next], { depth: info.get(queue[head]).depth + 1, order: next, right: false });
        if (side === 'right') info.get(queue[head]).right = true;
        queue.push(root[next]);
      }
      next++;
    }
  }
  if (root.slice(next).some(v => v !== null)) return 'Every node must have a parent earlier in the level-order array.';
  if (fromNode === toNode) return 'fromNode and toNode must be different.';
  const from = info.get(fromNode);
  const to = info.get(toNode);
  if (!from || !to) return 'fromNode and toNode must be values in the tree.';
  if (from.depth !== to.depth) return 'fromNode and toNode must be on the same depth.';
  if (to.order < from.order) return 'toNode must be to the right of fromNode.';
  if (from.right) return 'fromNode must have no right child in the given tree.';
  return null;
}

adapter:
function adapt(input, solve, kit) {
  const [values, fromNode, toNode] = input;
  const root = kit.toTree(values);
  // Plant the defect: the broken node's right link jumps sideways to toNode.
  kit.findNode(root, fromNode).right = kit.findNode(root, toNode);
  const result = solve(root);
  if (result === undefined) throw new Error('The solution did not return a value.');
  return kit.fromTree(result);
}

