function correctBinaryTree(root) {
  // A right-first depth-first walk reaches every node of a level before the nodes to its left,
  // so the broken node is the first one whose right child was already visited.
  const seen = new Set();
  const walk = (node, above) => {
    if (!node) return false;
    if (node.right && seen.has(node.right)) {
      if (above.left === node) above.left = null;
      else above.right = null;
      return true;
    }
    seen.add(node);
    return walk(node.right, node) || walk(node.left, node);
  };
  walk(root, null);
  return root;
}

generator:
function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  for (;;) {
    // At most 999 nodes keeps the level-order array under 2,000 entries.
    const n = size === 'large' ? 900 + pick(100) : 3 + pick(10);
    const deep = rand() < 0.3;
    const span = size === 'large' || rand() < 0.4 ? 1000000000 : 30;
    const used = new Set();
    const fresh = () => {
      for (;;) {
        const v = pick(2 * span + 1) - span;
        if (!used.has(v)) { used.add(v); return v; }
      }
    };
    const nodes = [{ val: fresh(), left: null, right: null }];
    while (nodes.length < n) {
      // Deep trees keep growing from the newest nodes; bushy trees attach a child anywhere.
      const parent = deep ? nodes[Math.max(0, nodes.length - 1 - pick(3))] : nodes[pick(nodes.length)];
      const side = rand() < 0.5 ? 'left' : 'right';
      if (parent[side]) continue;
      parent[side] = { val: fresh(), left: null, right: null };
      nodes.push(parent[side]);
    }
    const root = [];
    const rows = [];
    const queue = [[nodes[0], 0]];
    for (let q = 0; q < queue.length; q++) {
      const [node, depth] = queue[q];
      root.push(node ? node.val : null);
      if (!node) continue;
      (rows[depth] ??= []).push(node);
      queue.push([node.left, depth + 1], [node.right, depth + 1]);
    }
    while (root[root.length - 1] === null) root.pop();
    // The broken node has no right child and at least one node to its right on its level.
    const choices = [];
    rows.forEach(row => row.forEach((node, i) => { if (!node.right && i + 1 < row.length) choices.push([row, i]); }));
    if (choices.length === 0) continue;
    const [row, i] = choices[pick(choices.length)];
    const j = rand() < 0.4 ? i + 1 : i + 1 + pick(row.length - i - 1);
    return [root, row[i].val, row[j].val];
  }
}
